package app.streamnest;
import java.util.*;import org.json.*;
/** The complete upload allowlist. Never serialize Throwable messages or media metadata. */
final class DiagnosticData {
 static final Set<String> NUMBERS=new HashSet<>(Arrays.asList("elapsedMs processMemoryMb freeRamMb cacheFreeMb peers downloadKbps width height attempt percent status exitReason droppedFrames totalFrames bufferedMs bufferPercent audioTracks audioChannels sampleRate bitrateKbps volumePercent nativeCode audioDecodedBytes audioDecodedBuffers audioPlayedBuffers audioLostBuffers systemVolumePercent".split(" ")));
 static final Map<String,Set<String>> ENUMS=new HashMap<>();
 static {allow("service","catalog subtitles update sync torrent player storage app");allow("operation","fetch download verify install startup playback cache");allow("playState","playing paused buffering ended unknown");allow("systemAudioState","muted unmuted unknown");allow("audioState","muted unmuted disabled unknown");allow("videoCodec","h264 hevc av1 vp9 vp8 mpeg2 mpeg4 unknown");allow("audioCodec","aac ac3 eac3 dts opus vorbis mp3 flac pcm unknown");allow("decoder","hardware software auto unknown");allow("storage","internal external custom unknown");allow("stage","worker shutdown cache_check cache_prepare folder session_create engine_start cleanup unknown");allow("reason","low_memory native_crash java_crash anr user_stop unclean timeout network storage decoder integrity permission unknown");}
 static void allow(String k,String values){ENUMS.put(k,new HashSet<>(Arrays.asList(values.split(" "))));}
 static JSONObject clean(JSONObject raw){JSONObject out=new JSONObject();if(raw==null)return out;try{for(String k:NUMBERS){Object n=raw.opt(k);if(n instanceof Number){double d=((Number)n).doubleValue();if(Double.isFinite(d)&&d>=0&&d<=1e12&&d==Math.floor(d))out.put(k,((Number)n).longValue());}}for(String k:ENUMS.keySet())if(ENUMS.get(k).contains(raw.optString(k)))out.put(k,raw.getString(k));for(String k:new String[]{"errorClass","causeClass"})if(raw.optString(k).matches("(?:Error|[A-Za-z][A-Za-z0-9_$]{0,59}(?:Error|Exception))"))out.put(k,raw.getString(k));JSONArray frames=raw.optJSONArray("frames"),safe=new JSONArray();if(frames!=null)for(int i=0;i<frames.length()&&safe.length()<12;i++){String f=frames.optString(i);if(f.length()<=180&&f.matches("(?:app\\.streamnest|org\\.libtorrent4j|org\\.videolan|androidx|android|java|javax)\\.[A-Za-z0-9_.$]+:[0-9]{1,6}"))safe.put(f);}if(safe.length()>0)out.put("frames",safe);}catch(Exception ignored){}return out;}
 static JSONObject failure(String service,String operation,Throwable error){JSONObject data=new JSONObject();try{data.put("service",service).put("operation",operation);if(error!=null){data.put("errorClass",error.getClass().getSimpleName());Throwable cause=error;for(int i=0;i<3&&cause.getCause()!=null&&cause.getCause()!=cause;i++)cause=cause.getCause();data.put("causeClass",cause.getClass().getSimpleName());JSONArray frames=new JSONArray();for(StackTraceElement f:error.getStackTrace())if(frames.length()<12&&f.getLineNumber()>0)frames.put(f.getClassName()+"."+f.getMethodName()+":"+f.getLineNumber());data.put("frames",frames);java.util.regex.Matcher m=java.util.regex.Pattern.compile("\\bHTTP\\s+([1-5][0-9]{2})\\b").matcher(String.valueOf(cause.getMessage()));if(m.find())data.put("status",Integer.parseInt(m.group(1)));else{m=java.util.regex.Pattern.compile("^([1-5][0-9]{2})(?:\\s|$)").matcher(String.valueOf(cause.getMessage()));if(m.find())data.put("status",Integer.parseInt(m.group(1)));}data.put("reason",cause instanceof java.net.SocketTimeoutException?"timeout":cause instanceof java.net.UnknownHostException||cause instanceof java.net.ConnectException?"network":error instanceof OutOfMemoryError?"low_memory":"unknown");}}catch(Exception ignored){}return clean(data);}
 static String codec(String raw,boolean audio){String s=String.valueOf(raw).toLowerCase(java.util.Locale.ROOT);String result=s.contains("264")||s.equals("avc1")?"h264":s.contains("265")||s.contains("hevc")||s.equals("hvc1")?"hevc":s.contains("av01")||s.equals("av1")?"av1":s.contains("vp09")||s.equals("vp9")?"vp9":s.equals("vp8")?"vp8":s.equals("mpgv")?"mpeg2":s.equals("mp4v")?"mpeg4":s.contains("eac3")||s.equals("e-ac-3")?"eac3":s.contains("ac3")||s.equals("a52 ")?"ac3":s.contains("dts")?"dts":s.equals("mp4a")||s.contains("aac")?"aac":s.contains("opus")?"opus":s.contains("vorb")?"vorbis":s.equals("mpga")||s.contains("mp3")?"mp3":s.contains("flac")?"flac":s.contains("pcm")?"pcm":"unknown";return ENUMS.get(audio?"audioCodec":"videoCodec").contains(result)?result:"unknown";}
}
